(()=>{
'use strict';
const R=window.HerstoryPixelRenderer,dialog=document.querySelector('#planet-card'),canvas=document.querySelector('#pixel-preview'),status=document.querySelector('#pixel-status'),config={width:240,height:320,format:'RGB565',byteOrder:null,background:[0,0,0],...window.HERSTORY_PIXEL_CONFIG};
const profile=()=>window.HerstoryIdentity.getProfile();let state=null,isDemo=false,pane='photo',pending=false,pngBlob=null,encodeToken=0;
function fallback(){const p=profile();if(!R.palettes[p.paletteId])return null;return {paletteId:p.paletteId,aiCheckinCount:0,aiStage:0,lakeUnlocked:false,ruleVersion:'herstory-pixel-20261004-v1',stateVersion:0};}
function applySnapshot(data){if(data.userId&&data.userId!==profile().userId)throw Error('Pixel state belongs to another user');if(data.pixelPlanet){const next=R.validateState(data.pixelPlanet);if(next.paletteId!==profile().paletteId)throw Error('2D/3D palette mismatch');if(state&&!isDemo&&next.stateVersion<=state.stateVersion)return false;state={...next};isDemo=false;draw();return true;}if(!state){isDemo=!window.HERSTORY_INITIAL_STATE&&!window.HERSTORY_CONFIG?.endpoint;const base=fallback(),demo=window.HERSTORY_PIXEL_DEMO||{};state=isDemo&&base?{...base,aiCheckinCount:demo.aiCheckinCount??6,aiStage:demo.aiStage??Math.min(demo.aiCheckinCount??6,6),lakeUnlocked:demo.lakeUnlocked??true}:base;if(state)R.validateState(state);draw();}return false;}
function draw(){if(!state){canvas.hidden=true;status.textContent='像素星球正在同步';return;}canvas.hidden=false;const frame=R.renderFrame(state,{width:config.width,height:config.height});canvas.width=frame.width;canvas.height=frame.height;canvas.getContext('2d').imageSmoothingEnabled=false;canvas.getContext('2d').putImageData(new ImageData(frame.rgba,frame.width,frame.height),0,0);fitPreview();status.textContent=isDemo?'':state.stateVersion===0?'基础星球 · 等待同步':'';preparePNG();}
function fitPreview(){if(!canvas.width)return;const pages=document.querySelector('#card-pages'),sourceScale=Math.floor(Math.min(canvas.width,canvas.height)/R.SIZE),logicalScale=Math.max(1,Math.min(6,Math.floor(Math.min(pages.clientWidth/canvas.width,(pages.clientHeight-40)/canvas.height)*sourceScale)));canvas.style.width=(canvas.width*logicalScale/sourceScale)+'px';canvas.style.height=(canvas.height*logicalScale/sourceScale)+'px';}
new ResizeObserver(fitPreview).observe(document.querySelector('#card-pages'));
function selectPane(next){pane=next==='pixel'?'pixel':'photo';dialog.dataset.cardPane=pane;document.querySelector('#photo-pane').hidden=pane!=='photo';document.querySelector('#pixel-pane').hidden=pane!=='pixel';document.querySelector('#save-card').hidden=false;document.querySelector('#save-card').disabled=pane==='pixel'?!pngBlob:!window.HerstoryPhoto.getSaveState().ready;for(const b of document.querySelectorAll('[data-card-page]'))b.setAttribute('aria-pressed',String(b.dataset.cardPage===pane));if(pane==='pixel')draw();}
function authoritative(){if(!state||isDemo||state.stateVersion===0)throw Error('Authoritative pixel state not synchronized');return {...state};}
function exportFrame(options={}){const s={...state};if(!state)throw Error('Pixel state unavailable');R.validateState(s);const opts={...config,...options};if(opts.format==='RGB565'){const frame=R.encodeRGB565(s,opts);return {...frame,pixelPlanet:s,demo:isDemo,blob:new Blob([frame.bytes],{type:'application/octet-stream'})};}if(opts.format!=='PNG')throw Error('Unsupported frame format');const frame=R.renderFrame(s,{...opts,background:null}),c=document.createElement('canvas');c.width=frame.width;c.height=frame.height;c.getContext('2d').putImageData(new ImageData(frame.rgba,frame.width,frame.height),0,0);return new Promise((resolve,reject)=>c.toBlob(blob=>blob?resolve({...frame,pixelPlanet:s,demo:isDemo,blob}):reject(Error('Pixel PNG encoding failed')),'image/png'));}
function preparePNG(){const token=++encodeToken;pngBlob=null;if(pane==='pixel')document.querySelector('#save-card').disabled=true;exportFrame({format:'PNG'}).then(frame=>{if(token!==encodeToken)return;pngBlob=frame.blob;if(pane==='pixel')document.querySelector('#save-card').disabled=false;}).catch(()=>{if(token===encodeToken)status.textContent='图片未生成，请重试';});}
async function savePNG(){if(!pngBlob||pending)return;pending=true;const button=document.querySelector('#save-card');button.disabled=true;const name='Herstory-像素星球'+(isDemo?'-演示':'')+'.png';try{await window.HerstoryPhoto.saveImage(pngBlob,name);}catch(error){if(error.name!=='AbortError')status.textContent='图片保存失败，请重试';}finally{pending=false;button.disabled=pane==='pixel'?!pngBlob:!window.HerstoryPhoto.getSaveState().ready;}}
let start=null;const pages=document.querySelector('#card-pages');pages.addEventListener('pointerdown',e=>{if(!e.isPrimary)return;start={id:e.pointerId,x:e.clientX,y:e.clientY};pages.setPointerCapture(e.pointerId);});pages.addEventListener('pointerup',e=>{if(!start||start.id!==e.pointerId)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>48&&Math.abs(dx)>Math.abs(dy)*1.4)selectPane(dx>0?'pixel':'photo');});for(const event of ['pointercancel','lostpointercapture'])pages.addEventListener(event,()=>{start=null;});pages.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){selectPane('pixel');e.preventDefault();}if(e.key==='ArrowLeft'){selectPane('photo');e.preventDefault();}});
for(const b of document.querySelectorAll('[data-card-page]'))b.onclick=()=>selectPane(b.dataset.cardPage);document.querySelector('#save-card').onclick=()=>pane==='pixel'?savePNG():window.HerstoryPhoto.save();dialog.addEventListener('close',()=>selectPane('photo'));
window.HerstoryPixelPlanet={config,applySnapshot,selectPane,exportFrame,getSaveState(){return {ready:!!pngBlob&&!pending};},getState(){return {pixelPlanet:state?{...state}:null,demo:isDemo,pane};}};applySnapshot(window.HERSTORY_INITIAL_STATE||{});selectPane('photo');
})();
